
'use client';

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { LoginForm } from './LoginForm';
import { SignUpForm } from './SignUpForm';

interface AuthDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: 'login' | 'signup';
  onModeChange: (mode: 'login' | 'signup') => void;
  onSuccess: () => void;
}

export function AuthDialog({
  open,
  onOpenChange,
  mode,
  onModeChange,
  onSuccess,
}: AuthDialogProps) {
  const isLogin = mode === 'login';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="
          w-[calc(100vw-2rem)]
          max-w-[760px]
          sm:max-w-[760px]
          max-h-[92dvh]
          overflow-hidden
          rounded-3xl
          border border-slate-200
          bg-white
          p-0
          shadow-2xl
          flex
          flex-col
        "
      >
        {/* Accessible dialog title */}
        <DialogHeader className="sr-only">
          <DialogTitle>
            {isLogin
              ? 'Log In to ResearchPilot'
              : 'Create your ResearchPilot account'}
          </DialogTitle>

          <DialogDescription>
            {isLogin
              ? 'Enter your credentials to access your ResearchPilot account.'
              : 'Create an account to personalize your research discovery experience.'}
          </DialogDescription>
        </DialogHeader>

        {/* Scrollable authentication content */}
        <div
          className="
            min-h-0
            overflow-y-auto
            overscroll-contain
            p-6
            sm:p-8
            md:p-10
          "
        >
          {/* Header */}
          <div className="mb-7 text-center sm:mb-8">
            <div
              className="
                mx-auto
                mb-4
                flex
                h-12
                w-12
                items-center
                justify-center
                rounded-2xl
                bg-indigo-50
              "
            >
              <div className="h-2.5 w-2.5 rounded-full bg-indigo-600" />
            </div>

            <h2 className="text-2xl font-semibold tracking-tight text-slate-900 sm:text-3xl">
              {isLogin ? 'Welcome back' : 'Create your account'}
            </h2>

            <p className="mx-auto mt-2 max-w-lg text-sm leading-6 text-slate-500 sm:text-base">
              {isLogin
                ? 'Continue your personalized research journey.'
                : 'Set up your research profile to get started.'}
            </p>
          </div>

          {/* Form */}
          {isLogin ? (
            <LoginForm onSuccess={onSuccess} />
          ) : (
            <SignUpForm onSuccess={onSuccess} />
          )}

          {/* Switch Login / Signup */}
          <div
            className="
              mt-7
              border-t
              border-slate-100
              pt-5
              text-center
              text-sm
              text-slate-500
              sm:mt-8
              sm:pt-6
            "
          >
            {isLogin
              ? "Don't have an account?"
              : 'Already have an account?'}

            <button
              type="button"
              onClick={() =>
                onModeChange(isLogin ? 'signup' : 'login')
              }
              className="
                ml-1
                font-medium
                text-indigo-600
                transition-colors
                hover:text-indigo-800
                hover:underline
              "
            >
              {isLogin ? 'Sign up' : 'Log in'}
            </button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
